(()=>{const e=window.menuClicks?.url;if(!e||!navigator.sendBeacon)return;const t=t=>{const n=t.target instanceof Element?t.target.closest("a[data-menu-item]"):null;!n||"click"!==t.type&&1!==t.button||navigator.sendBeacon(e,new URLSearchParams({item:n.dataset.menuItem}))};document.addEventListener("click",t,{capture:!0}),document.addEventListener("auxclick",t,{capture:!0})})();